"""
The record: one thing in the data with an id, its join keys and everything else as attrs.

All records share one set of join columns, so link rules are plain merges on those columns.
"""

RECORD_COLUMNS = [
    "record_id",  # '<kind>:<key>'
    "kind",
    "key",
    "source",  # portal path of the file it came from
    "source_sha256",  # exact file version
    "supplier_id",
    "material_id",
    "po_number",
    "po_line",
    "gr_number",
    "batch",
    "delivery_note",
    "shipment_id",
    "po_numbers",  # list
    "material_ids",  # list
    "attrs",  # dict: everything that is not a join key
]

# Kinds every chain passes through; trace does not walk across them.
HUB_KINDS = {"part", "supplier"}


def make_record(kind: str, key: str, source, attrs: dict | None = None, **keys) -> dict:
    record = dict.fromkeys(RECORD_COLUMNS)
    record.update(
        record_id=f"{kind}:{key}",
        kind=kind,
        key=key,
        source=source.path,
        source_sha256=source.sha256,
        attrs=attrs or {},
        **keys,
    )
    return record
"""
Linker: connects every record that describes the same order, delivery or lot.

Pipeline: discover (classify files) → adapters (files → records) → rules (records → links and
issues) → graph (save, trace). Everything is rebuilt from the portal data on each run.
"""

from verifier.linker.graph import Graph, build

__all__ = ["Graph", "build"]
"""
Cleanup functions: turn the different spellings of the same key into one.

Pure functions only. No values from the portal data live here; supplier ids are learned from the
supplier profiles at runtime.
"""

import re
from datetime import date, datetime

_LIST_SEP = re.compile(r"\s*[|,;]\s*")
_NON_ALNUM = re.compile(r"[^0-9a-z]+")


def is_blank(value) -> bool:
    if value is None:
        return True
    if isinstance(value, float) and value != value:  # NaN
        return True
    return isinstance(value, str) and not value.strip()


def clean(value) -> str | None:
    """Strip a value to a string, or None when it is empty or missing."""
    return None if is_blank(value) else str(value).strip()


def split_list(value) -> list[str]:
    """Split a joined list such as 'a|b' or 'a, b' into its parts."""
    text = clean(value)
    if text is None:
        return []
    return [part for part in _LIST_SEP.split(text) if part]


def po_line(value) -> str | None:
    """
    Bring PO line numbers to one form.

    SAP item numbers are zero-padded and count in steps of ten ('00010' is line 1, '00510' is
    line 51). Plain numbers ('1') are taken as they are.
    """
    text = clean(value)
    if text is None or not text.isdigit():
        return text
    number = int(text)
    if len(text) >= 5 and text.startswith("0") and number % 10 == 0:
        return str(number // 10)
    return str(number)


def parse_number(value, decimal_comma: bool = False) -> float | None:
    """Parse '1,5200' (decimal comma) or '44,000' (thousands comma). None when unparseable."""
    text = clean(value)
    if text is None:
        return None
    text = text.replace(" ", "").replace(" ", "")
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    try:
        return float(text)
    except ValueError:
        return None


def parse_date(value, formats: tuple[str, ...] = ("%Y-%m-%d",)) -> str | None:
    """Return an ISO date (YYYY-MM-DD), or None when the value matches none of the formats."""
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    text = clean(value)
    if text is None:
        return None
    for fmt in formats:
        try:
            return datetime.strptime(text, fmt).date().isoformat()
        except ValueError:
            continue
    return None


def name_key(value) -> str:
    """Comparable form of a name: lower case, letters and digits only."""
    return _NON_ALNUM.sub("", str(value).lower())


class SupplierResolver:
    """
    Maps every way the data names a supplier to one supplier id.

    Learned from the supplier profiles: the id itself ('SUP-0019'), its number ('19'), the name,
    the legal name and the portal folder name ('SUP-0019_Dongguan_Precision_Housings').
    """

    def __init__(self, profiles: list[dict]):
        self._by_key: dict[str, str] = {}
        self._by_number: dict[int, str] = {}
        for profile in profiles:
            supplier_id = clean(profile.get("supplier_id"))
            if supplier_id is None:
                continue
            for name in (supplier_id, profile.get("name"), profile.get("legal_name")):
                if clean(name):
                    self._by_key[name_key(name)] = supplier_id
            for number in (re.sub(r"\D", "", supplier_id), clean(profile.get("vendor_no"))):
                if number and number.isdigit():
                    self._by_number[int(number)] = supplier_id

    def resolve(self, value) -> str | None:
        text = clean(value)
        if text is None:
            return None
        if text.isdigit():
            return self._by_number.get(int(text))
        found = self._by_key.get(name_key(text))
        if found:
            return found
        # Folder names: '<id>_<name>'
        head = text.split("_", 1)[0]
        return self._by_key.get(name_key(head)) if head != text else None
"""
Classify every portal file by what it contains, not by its exact name.

Spreadsheets are recognised by their columns, documents by their filename pattern. A file that
matches nothing is reported as 'unknown', so a new kind of file shows up instead of being skipped.
"""

import hashlib
import json
import re
from dataclasses import dataclass, field
from pathlib import Path

import openpyxl

# Spreadsheet layouts: kind → columns a file must have. The most specific match wins.
CSV_LAYOUTS: dict[str, frozenset[str]] = {
    "purchase_orders": frozenset(
        {"po_number", "po_line", "supplier_id", "material_id", "quantity"}
    ),
    "purchase_orders_sap": frozenset({"EBELN", "EBELP", "LIFNR", "MATNR", "MENGE"}),
    "goods_receipts": frozenset(
        {"gr_number", "po_number", "po_line", "delivery_note", "qty_received"}
    ),
    "stock": frozenset({"snapshot_date", "material_id", "batch", "quantity"}),
    "shipments": frozenset({"shipment_id", "po_numbers", "material_ids", "eta", "status"}),
    "supplier_profile": frozenset({"supplier_id", "name", "legal_name", "qualification_status"}),
    "parts_master": frozenset({"component_id", "description", "abc_class", "drawing_rev"}),
}
XLSX_LAYOUTS: dict[str, frozenset[str]] = {
    "shipment_tracker": frozenset({"Shipment", "POs", "Status"}),
}
XLSX_HEADER_SEARCH_ROWS = 10
# JSON layouts: kind → dotted key paths a file must have.
JSON_LAYOUTS: dict[str, frozenset[str]] = {
    "supplier_profile_json": frozenset({"supplier.supplierId", "supplier.name"}),
}

# Documents: kind → filename pattern. Named groups become the document's keys.
DOC_PATTERNS: list[tuple[str, re.Pattern]] = [
    ("confirmation", re.compile(r"^OA(?P<conf>\w+?)_(?P<po_number>\d+)\.pdf$", re.I)),
    (
        "shipping_advice",
        re.compile(r"^Shipping_advice_(?P<awb>[\w-]+)_(?P<po_number>\d+)\.pdf$", re.I),
    ),
    ("packing_list", re.compile(r"^PL_(?P<ref>\w+)_(?P<po_number>\d+)\.pdf$", re.I)),
    (
        "delivery_note",
        re.compile(
            r"^(?P<date>\d{8})_(?P<delivery_note>[A-Z]{2,4}-\d{6}-\d{3})\.(?:jpe?g|png|pdf)$", re.I
        ),
    ),
    ("inspection_report", re.compile(r"^inspection_report_(?P<batch>\d+)\.pdf$", re.I)),
]


@dataclass(frozen=True)
class Source:
    path: str  # relative to the portal root, '/'-separated
    abspath: Path
    kind: str
    sha256: str
    meta: dict = field(default_factory=dict)


def sniff_separator(first_line: str) -> str:
    return ";" if first_line.count(";") > first_line.count(",") else ","


def csv_header(path: Path) -> set[str]:
    with path.open(encoding="utf-8-sig") as handle:
        first = handle.readline().strip()
    return {col.strip() for col in first.split(sniff_separator(first))}


def find_xlsx_table(path: Path, required: frozenset[str]) -> tuple[str, int] | None:
    """Return (sheet name, header row index) of the first sheet whose header holds `required`."""
    workbook = openpyxl.load_workbook(path, read_only=True, data_only=True)
    try:
        for sheet in workbook.worksheets:
            for index, row in enumerate(sheet.iter_rows(values_only=True)):
                if index >= XLSX_HEADER_SEARCH_ROWS:
                    break
                cells = {str(cell).strip() for cell in row if cell is not None}
                if required <= cells:
                    return sheet.title, index
    finally:
        workbook.close()
    return None


def flatten(value, prefix: str = "") -> dict:
    """{'a': {'b': 1}} → {'a.b': 1}. Lists are kept as values."""
    if not isinstance(value, dict):
        return {prefix: value}
    flat = {}
    for key, inner in value.items():
        flat.update(flatten(inner, f"{prefix}.{key}" if prefix else str(key)))
    return flat


def load_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8-sig"))


def _best_layout(header: set[str], layouts: dict[str, frozenset[str]]) -> str | None:
    matches = [(len(cols), kind) for kind, cols in layouts.items() if cols <= header]
    return max(matches)[1] if matches else None


def classify(path: Path) -> tuple[str, dict]:
    name = path.name
    for kind, pattern in DOC_PATTERNS:
        match = pattern.match(name)
        if match:
            return kind, match.groupdict()
    suffix = path.suffix.lower()
    try:
        if suffix == ".csv":
            kind = _best_layout(csv_header(path), CSV_LAYOUTS)
            if kind:
                return kind, {}
        elif suffix in (".xlsx", ".xlsm"):
            for kind, required in XLSX_LAYOUTS.items():
                table = find_xlsx_table(path, required)
                if table:
                    return kind, {"sheet": table[0], "header_row": table[1]}
        elif suffix == ".json":
            kind = _best_layout(set(flatten(load_json(path))), JSON_LAYOUTS)
            if kind:
                return kind, {}
    except Exception as error:  # a broken file is reported, never fatal
        return "unknown", {"error": f"{type(error).__name__}: {error}"}
    return "unknown", {}


def discover(root: Path) -> list[Source]:
    sources = []
    for path in sorted(root.rglob("*")):
        if not path.is_file() or any(part.startswith(".") for part in path.relative_to(root).parts):
            continue
        kind, meta = classify(path)
        sha = hashlib.sha256(path.read_bytes()).hexdigest()
        sources.append(Source(path.relative_to(root).as_posix(), path, kind, sha, meta))
    return sources

